use genex::prelude::*;

pub fn wire(game: &mut Game<super::World>) {
    game.on_reset(|sim, _seed, _rng, gfx| {
        sim.world.crate_model = Some(gfx.assets().model("cc0/<job>/wooden_crate_01_1k.glb"));
    });
    game.on_draw(|sim, frame, _camera| {
        if let Some(model) = &sim.world.crate_model {
            frame.tag("crate").model(model, Transform::from_translation(sim.world.crate_at));
        }
    });
}
